pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Restrict domain to admissible values: amount must be >0 for the property to be non-trivial,
        // and must be <= the starting balance we can deal to a caller. Keep it wide.
        bound(amount, 1, 1_000_000 ether);

        // 2. Set up: fund a caller and record the owner's initial balance.
        address caller = makeAddr("caller");
        vm.deal(caller, amount);
        address owner = c.owner();
        uint256 ownerBefore = owner.balance;

        // 3. Call go() as the funded caller with the fuzzed amount as msg.value.
        vm.prank(caller);
        c.go{value: amount}();

        // 4. Assert: the owner's balance must have increased by exactly the amount sent.
        // The reference contract forwards all value in the low-level call, then transfers the
        // contract's remaining balance (which is 0) to the owner, leaving the owner unchanged
        // from an ETH perspective of this call. Wait: the low-level call sends msg.value to
        // 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C. That address is a precompile or EOA that
        // may reject? It's a valid address. The call{value: msg.value} sends the Ether away.
        // Then transfer(address(this).balance) sends 0. So owner balance does NOT increase.
        // The mutant sends value:0, so msg.value stays in the contract, then transfer sends it to
        // owner, increasing owner's balance by msg.value. So the property is reversed:
        // Reference: owner balance unchanged. Mutant: owner balance increases by msg.value.
        // We express: after go(), owner's balance == ownerBefore (reference holds, mutant fails).
        assertTrue(owner.balance == ownerBefore);
    }
}

