import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 preFunds, uint256 callValue) public {
        vm.assume(preFunds <= type(uint128).max);
        vm.assume(callValue <= type(uint128).max);
        vm.assume(address(c).balance == 0);

        // Seed the contract with preFunds (simulating prior balance)
        if (preFunds > 0) {
            vm.deal(address(this), preFunds);
            (bool s,) = address(c).call{value: preFunds}("");
            require(s, "seed failed");
        }

        // Fund a caller and invoke go with callValue
        address caller = address(0x1234);
        vm.deal(caller, callValue);
        vm.prank(caller);
        c.go{value: callValue}();

        // After go(), the correct contract has always transferred its entire balance to owner.
        // Therefore, c's balance must be 0.
        assertTrue(address(c).balance == 0);
    }
}

