pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 preBalance, uint256 callValue) public {
        // Admissible domain: preBalance can be any value, but callValue must be less than or equal to preBalance if target call needs it,
        // and both should be manageable. Keep domain wide but avoid overflow.
        vm.assume(preBalance <= type(uint128).max);
        vm.assume(callValue <= type(uint128).max);
        vm.assume(callValue <= preBalance);

        // Fund the contract with preBalance (simulate prior deposits)
        vm.deal(address(c), preBalance);

        // Record balance before the call
        uint256 balanceBefore = address(c).balance;

        // We need to ensure the target call succeeds to isolate the transfer difference.
        // The hardcoded target 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C might revert if it has no code;
        // assume it is a precompile or an EOA — low-level call to an EOA always succeeds.
        // To make the test robust, we use a helper that accepts Ether.
        // But per rules, we cannot change the target inside C; we must route through it as-is.
        // The target is a constant address. If it has no code, call to it succeeds anyway.
        // We prank a caller with enough Ether to supply msg.value.
        address caller = makeAddr("caller");
        vm.deal(caller, callValue);
        vm.prank(caller);
        c.go{value: callValue}();

        uint256 balanceAfter = address(c).balance;

        // Rule: balanceBefore - balanceAfter == callValue (all value sent is taken, plus any existing balance is swept)
        // For reference C, balanceAfter is always 0 after a successful go(), so balanceBefore - balanceAfter == balanceBefore.
        // But the actual invariant we assert is that the difference equals the value sent.
        // Since reference C transfers entire balance to owner, balanceAfter = 0, so diff = balanceBefore.
        // The invariant holds: balanceBefore - 0 = callValue + (balanceBefore - callValue) = balanceBefore? Wait.
        // Let's be precise: The rule we want is "the owner receives the entire contract balance",
        // but we only have owner getter. The owner's balance change is not easily assertable without extra setup.
        // So we use a proxy: after go(), contract balance must be zero for every successful call.
        // That is a universal property that reference satisfies and mutant breaks when preBalance > callValue.
        assertTrue(balanceAfter == 0);
    }
}

