pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 balanceBefore, uint256 callValue) public {
        // Restrict to the admissible domain: call value must not exceed the pre-existing balance plus the call value,
        // and we avoid overflow in the combined funding. Also ensure the call value is non-zero to trigger interaction.
        vm.assume(balanceBefore <= type(uint128).max);
        vm.assume(callValue > 0 && callValue <= type(uint128).max);
        vm.assume(balanceBefore + callValue <= type(uint128).max);

        // Fund the contract with a pre-existing balance
        vm.deal(address(c), balanceBefore);

        // Fund the caller with the call value
        address caller = makeAddr("caller");
        vm.deal(caller, callValue);

        // Execute go() with msg.value
        vm.prank(caller);
        c.go{value: callValue}();

        // After the call, the contract's balance must be zero (all funds sent to owner)
        assertEq(address(c).balance, 0, "Contract balance should be zero after go()");
    }
}
